response:
I assumed the script keeps round 3's calling pattern. The runner `python spe/evals/harness/run_trial.py --config --ticket --trial --out` prints one JSON result and writes a result file and a transcript. `grade.py` takes result file paths. Ticket ids run T01 to T50. You can change any of these through args.

**Gates before launch.** I check four things in order before I start the run.
1. `spe/predictions/r04.yaml` and `spe/plans/r04.md` must both be committed, and they are.
2. The grader selftest must pass. `grade.py` must pass an oracle result built from `answers.json`. It must fail an empty label and a wrong label on the same tickets.
3. I regrade round 3's saved results with this round's `grade.py` and `judge.md`. This is the control. If round 3's numbers move, the graders changed, and I log that as a failure before I compare B and C2.
4. I do a dry run with `{"only": ["B:T01", "C2:T01", "C2:T02"], "trialsPerCell": 2}`. Dry-run output goes to `spe/runs/r04-dry`. I check that every trial returns schema-valid output and that the grader rows match the trial ids. I also check that the peek scan finds no false hits and that the measured cost per trial is close to `estTrialUsd`.

If the dry-run cost per trial would push 500 trials plus judging past $40, I stop and ask you before launching. The dollar estimates in the script are guesses until the dry run measures them. When all four gates pass, I commit the script as `SPE r04 evaluate (harness)`. Then I launch it without `only`.

```js
export const meta = {
  name: 'spe-round-eval',
  description: 'SPE eval for one round: configs B and C2 on the ticket set, code grader first, blind Opus tone judge second, top-up on split cells, then failure analysis and a completeness critic.',
  phases: [
    { title: 'Trials' },
    { title: 'Grade' },
    { title: 'Judge' },
    { title: 'Top-up' },
    { title: 'Synthesis' },
  ],
}

// The round lives here and nowhere else. Paths and prompts derive from it.
const ROUND = 4
const R = `r${String(ROUND).padStart(2, '0')}`

const A = args || {}
const CONFIGS = A.configs ?? ['B', 'C2']
const TICKETS = A.ticketIds ?? Array.from({ length: 50 }, (_, i) => `T${String(i + 1).padStart(2, '0')}`)
const TRIALS = A.trialsPerCell ?? 5
const ONLY = A.only ?? null // dry run, for example ['B:T01', 'C2:T01', 'C2:T02']
const MODEL = A.model ?? 'opus'
const RUNNER = A.runnerCmd ?? 'python spe/evals/harness/run_trial.py'
const GRADER = 'python spe/evals/graders/grade.py'
const OUT = A.outDir ?? `spe/runs/${R}${ONLY ? '-dry' : ''}`

// Paid resources. The cap comes from the approved plan. The per-call figures are
// unmeasured estimates from last round's means until the dry run measures them.
const CAP_USD = A.spendCapUsd ?? 40
const JUDGE_POOL_USD = A.judgePoolUsd ?? 8
const TRIAL_POOL_USD = CAP_USD - JUDGE_POOL_USD
const EST_TRIAL_USD = A.estTrialUsd ?? 0.05
const EST_JUDGE_USD = A.estJudgeUsd ?? 0.15
const MAX_AGENTS = A.maxAgents ?? 1000
const TOPUP_PER_CELL = A.topupPerCell ?? 5
const TOPUP_MAX = A.topupMaxTrials ?? 100
const MAX_GRADER_ERROR_RATE = 0.1

const FORBIDDEN = ['spe/evals/', 'spe/predictions/', 'spe/plans/', 'spe/runs/', 'spe/prediction-log.md', 'spe/failures.md']
const PEEK_TERMS = [...FORBIDDEN, 'answers.json', 'grade.py', 'judge.md']
const PEEK_ARGS = PEEK_TERMS.map(p => `-e '${p}'`).join(' ')
const JUDGE_NOTE = 'The tone judge is Opus. No judge from a different model family is available here, so tone scores share Claude blind spots.'

// ---------- schemas ----------
const TRIAL_SCHEMA = {
  type: 'object',
  required: ['status'],
  properties: {
    status: { enum: ['completed', 'harness_error', 'rate_limited'] },
    label: {
      type: ['object', 'null'],
      properties: { category: { type: 'string' }, priority: { type: 'string' } },
    },
    reply: { type: 'string' },
    result_path: { type: 'string' },
    transcript_path: { type: 'string' },
    runtime_s: { type: 'number' },
    tool_calls: { type: 'integer' },
    tool_errors: { type: 'integer' },
    input_tokens: { type: 'integer' },
    output_tokens: { type: 'integer' },
    cost_usd: { type: 'number' },
    error: { type: 'string' },
  },
}

const GRADE_SCHEMA = {
  type: 'object',
  required: ['items'],
  properties: {
    items: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'category_ok', 'priority_ok', 'peeked'],
        properties: {
          id: { type: 'string' },
          category_ok: { type: 'boolean' },
          priority_ok: { type: 'boolean' },
          grader_error: { type: ['string', 'null'] },
          peeked: { type: 'boolean' },
          peek_evidence: { type: ['string', 'null'] },
        },
      },
    },
  },
}

const JUDGE_SCHEMA = {
  type: 'object',
  required: ['items'],
  properties: {
    items: {
      type: 'array',
      items: {
        type: 'object',
        required: ['rid', 'tone_score', 'tone_pass', 'reason'],
        properties: {
          rid: { type: 'string' },
          tone_score: { type: 'number' },
          tone_pass: { type: 'boolean' },
          reason: { type: 'string' },
        },
      },
    },
  },
}

const FAIL_SCHEMA = {
  type: 'object',
  required: ['types', 'grader_bugs_suspected'],
  properties: {
    types: {
      type: 'array',
      items: {
        type: 'object',
        required: ['failure_id', 'name', 'kind', 'configs', 'count', 'example_ids', 'what', 'how_to_spot', 'proposed_fix'],
        properties: {
          failure_id: { type: 'string' },
          name: { type: 'string' },
          kind: { enum: ['agent', 'grader', 'harness', 'task'] },
          configs: { type: 'array', items: { type: 'string' } },
          count: { type: 'integer' },
          example_ids: { type: 'array', items: { type: 'string' } },
          what: { type: 'string' },
          how_to_spot: { type: 'string' },
          proposed_fix: { type: 'string' },
        },
      },
    },
    grader_bugs_suspected: { type: 'array', items: { type: 'string' } },
    notes: { type: 'string' },
  },
}

const CRITIC_SCHEMA = {
  type: 'object',
  required: ['verdict', 'gaps'],
  properties: {
    verdict: { enum: ['complete', 'gaps'] },
    gaps: {
      type: 'array',
      items: {
        type: 'object',
        required: ['what', 'severity', 'fix'],
        properties: {
          what: { type: 'string' },
          severity: { enum: ['blocks_results', 'note'] },
          fix: { type: 'string' },
        },
      },
    },
  },
}

// ---------- budget ledger ----------
const pools = {
  trial: { cap: TRIAL_POOL_USD, spent: 0, held: 0 },
  judge: { cap: JUDGE_POOL_USD, spent: 0, held: 0 },
}
const skips = []
let agentsUsed = 0

const r2 = x => Math.round(x * 100) / 100
const r3 = x => (x == null ? null : Math.round(x * 1000) / 1000)

function reserve(pool, est, what) {
  if (agentsUsed >= MAX_AGENTS) {
    skips.push({ what, reason: 'agent cap', agents_used: agentsUsed })
    log(`SKIP ${what}: agent cap of ${MAX_AGENTS} reached`)
    return false
  }
  if (pool) {
    const p = pools[pool]
    if (p.spent + p.held + est > p.cap) {
      skips.push({ what, reason: `${pool} pool cap`, spent: r2(p.spent), held: r2(p.held), cap: p.cap })
      log(`SKIP ${what}: ${pool} pool would cross $${p.cap} (spent $${r2(p.spent)}, held $${r2(p.held)})`)
      return false
    }
    p.held += est
  }
  agentsUsed += 1
  return true
}

async function paidAgent(pool, est, what, prompt, opts) {
  if (!reserve(pool, est, what)) return { skipped: true }
  let out = null
  let error = null
  try {
    out = await agent(prompt, { ...opts, model: MODEL })
  } catch (e) {
    error = String((e && e.message) || e)
  }
  if (pool) {
    const actual = out && typeof out.cost_usd === 'number' ? out.cost_usd : est
    pools[pool].held -= est
    pools[pool].spent += actual
  }
  return { out, error }
}

function ledgerOut() {
  return {
    cap_usd: CAP_USD,
    trial_pool: { cap: TRIAL_POOL_USD, spent: r2(pools.trial.spent) },
    judge_pool: { cap: JUDGE_POOL_USD, spent_estimated: r2(pools.judge.spent) },
    agents_used: agentsUsed,
    max_agents: MAX_AGENTS,
    note: 'Judge spend and any trial that reported no cost_usd are charged at the estimate.',
  }
}

function hash(s) {
  let h = 2166136261
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i)
    h = Math.imul(h, 16777619)
  }
  return h >>> 0
}

// ---------- prompts ----------
function trialPrompt(config, ticket, k) {
  return `You operate one eval trial. Run one command and report what it printed.

Run exactly this from the repository root:
${RUNNER} --config ${config} --ticket ${ticket} --trial ${k} --out ${OUT}

Rules:
1. Do not read, open, list, or search any file or directory. Running the command above is the only exception. Never touch these paths: ${FORBIDDEN.join(', ')}.
2. Do not edit files. Do not rerun the command with other flags.
3. If the command exits nonzero or prints no JSON, set status to "harness_error" and put the last 20 lines of its error output in error.
4. If the output says the request was rate limited, set status to "rate_limited".
5. Otherwise set status to "completed" and copy every field from the printed JSON unchanged. Copy reply verbatim. Do not judge or correct the label.`
}

function gradePrompt(todo) {
  const rows = todo
    .map(t => `- id ${t.id} | result ${t.result_path} | transcript ${t.transcript_path || 'MISSING'}`)
    .join('\n')
  return `You are the code grader for an eval. You may read spe/evals/graders/, spe/evals/tasks/, and the files listed below.

Step 1. Run the grader on every result file in one call:
${GRADER} ${todo.map(t => t.result_path).join(' ')}
Report category_ok and priority_ok exactly as the grader prints them. Do not grade by eye and do not edit the grader. If the grader fails on a file, set grader_error to its message and set both checks to false.

Step 2. Scan each transcript for peeking with:
rg -n -F ${PEEK_ARGS} <transcript>
Set peeked to true only when a hit is a tool call by the agent under test that reads, lists, or searches one of those paths. Hits in the runner's header or in the config prompt do not count. Quote the hit in peek_evidence. If a transcript is MISSING, set peeked to false and set grader_error to "transcript missing".

Files:
${rows}

Return one item per id.`
}

function judgePrompt(ticket, blind) {
  const replies = blind.map(b => `### ${b.rid}\n${b.t.reply || '(empty reply)'}`).join('\n\n')
  return `You judge the tone of support replies. Read the rubric in spe/evals/graders/judge.md and follow it exactly. Read the ticket text for ${ticket} from spe/evals/tasks/. Do not open spe/evals/tasks/answers.json. Label correctness is graded elsewhere and is not your concern.

The replies below come from different agent setups in a shuffled order. Judge each one on its own against the rubric. Do not try to guess which setup wrote it.

${replies}

Return one item per reply id with tone_score on the rubric's scale, tone_pass by the rubric's pass line, and a one-sentence reason.`
}

function failurePrompt(rows, total) {
  const list = rows
    .map(t => `- ${t.id} | category_ok ${t.category_ok} | priority_ok ${t.priority_ok} | tone_pass ${t.tone_pass ?? 'n/a'} | label ${JSON.stringify(t.label ?? null)} | result ${t.result_path} | transcript ${t.transcript_path}`)
    .join('\n')
  return `You analyze failures from SPE eval round ${ROUND}. Configs: ${CONFIGS.join(', ')}. ${total} graded trials failed the code check or the tone check. The ${rows.length} listed below are a sample with up to 40 per config.

You may read the listed result files and transcripts, spe/evals/tasks/answers.json, spe/evals/graders/grade.py, spe/evals/graders/judge.md, and spe/failures.md.

${list}

Group the failures into types. For each type, reuse the F-number from spe/failures.md when it matches, or set failure_id to "new". Give a name, the kind (agent, grader, harness, or task), the configs it hit, a count, up to 3 example ids, what happened, how to spot it, and a proposed fix for round ${ROUND + 1}. If a failure looks like the grader or the answer key is wrong rather than the agent, list it under grader_bugs_suspected. A grader bug counts as a failure. Do not edit any file.`
}

function criticPrompt(summary, fa) {
  return `You are the completeness critic for SPE eval round ${ROUND}. The plan: configs ${CONFIGS.join(' and ')}, ${summary.tickets} tickets, ${TRIALS} trials per cell, a code grader for label.category and label.priority, then an Opus tone judge, with a spend cap of $${CAP_USD}.

Check each of these and report every gap:
1. Every planned trial is accounted for as completed, voided for peeking, harness error, grader error, or skipped with a reason.
2. Every completed trial has a tone score or a logged judge error.
3. The metrics count only completed, non-voided trials.
4. Skips and voids are listed with reasons.
5. The failure analysis covers each config.
You may list files under ${OUT} to confirm that result files exist. Do not edit anything.

Summary:
${JSON.stringify(summary, null, 2)}

Failure analysis:
${JSON.stringify(fa, null, 2)}`
}

// ---------- steps ----------
const all = []
const valid = t => t.status === 'completed' && t.graded && !t.grader_error && !t.peeked

async function runTrial(config, ticket, k, kind) {
  const id = `${config}:${ticket}:${k}`
  const base = { id, config, ticket, k, kind }
  const res = await paidAgent('trial', EST_TRIAL_USD, `trial ${id}`, trialPrompt(config, ticket, k), {
    label: `trial ${id}`,
    phase: kind === 'base' ? 'Trials' : 'Top-up',
    schema: TRIAL_SCHEMA,
  })
  if (res.skipped) return { ...base, status: 'skipped_cap' }
  if (res.error || !res.out || !res.out.status) {
    return { ...base, status: 'harness_error', error: res.error || 'no structured output' }
  }
  return { ...base, ...res.out }
}

async function gradeCell(cell, trials, phaseName) {
  const todo = trials.filter(t => t.status === 'completed' && t.result_path && !t.graded)
  if (!todo.length) return
  const res = await paidAgent(null, 0, `grade ${cell.key}`, gradePrompt(todo), {
    label: `grade ${cell.key}`,
    phase: phaseName,
    schema: GRADE_SCHEMA,
  })
  const rows = (res.out && res.out.items) || []
  const byId = new Map(rows.map(g => [g.id, g]))
  for (const t of todo) {
    const g = byId.get(t.id)
    t.graded = true
    if (!g) {
      t.grader_error = res.error || (res.skipped ? 'grade skipped at cap' : 'grader returned no row')
      continue
    }
    t.category_ok = !!g.category_ok
    t.priority_ok = !!g.priority_ok
    t.grader_error = g.grader_error || null
    t.peeked = !!g.peeked
    t.peek_evidence = g.peek_evidence || null
    t.pass = t.category_ok && t.priority_ok
    if (t.peeked) log(`VOID ${t.id}: peeked (${t.peek_evidence})`)
  }
}

async function judgeTicket(ticket, kind, phaseName) {
  const items = all.filter(t => t.ticket === ticket && t.kind === kind && valid(t) && t.tone_score == null)
  if (!items.length) return
  const blind = items
    .map(t => ({ t, key: hash(`${R}:${kind}:${t.id}`) }))
    .sort((a, b) => a.key - b.key)
    .map((x, i) => ({ rid: `x${i + 1}`, t: x.t }))
  const res = await paidAgent('judge', EST_JUDGE_USD, `judge ${ticket} ${kind}`, judgePrompt(ticket, blind), {
    label: `judge ${ticket} ${kind}`,
    phase: phaseName,
    schema: JUDGE_SCHEMA,
  })
  if (res.skipped || !res.out) {
    for (const b of blind) b.t.judge_error = res.error || 'judge skipped at cap'
    return
  }
  const byRid = new Map(res.out.items.map(j => [j.rid, j]))
  for (const b of blind) {
    const j = byRid.get(b.rid)
    if (!j) {
      b.t.judge_error = 'no judge row'
      continue
    }
    b.t.tone_score = j.tone_score
    b.t.tone_pass = !!j.tone_pass
    b.t.tone_reason = j.reason
  }
}

// ---------- run ----------
const cells = []
for (const config of CONFIGS) {
  for (const ticket of TICKETS) {
    const key = `${config}:${ticket}`
    if (!ONLY || ONLY.includes(key)) cells.push({ key, config, ticket })
  }
}
const TICKETS_IN_RUN = [...new Set(cells.map(c => c.ticket))]

phase('Trials')
log(`Round ${ROUND}${ONLY ? ' DRY RUN' : ''}: ${cells.length} cells x ${TRIALS} trials. Out: ${OUT}. Cap $${CAP_USD} (trials $${TRIAL_POOL_USD}, judge $${JUDGE_POOL_USD}).`)

await pipeline(
  cells,
  async cell => {
    const ts = await parallel(
      Array.from({ length: TRIALS }, (_, i) => () => runTrial(cell.config, cell.ticket, i + 1, 'base')),
    )
    all.push(...ts)
    return { cell, ts }
  },
  async ({ cell, ts }) => {
    await gradeCell(cell, ts, 'Grade')
    return cell
  },
)

phase('Grade')
const completedBase = all.filter(t => t.status === 'completed')
const graderErrors = completedBase.filter(t => t.grader_error)
log(`Base: ${completedBase.length} completed, ${graderErrors.length} grader errors, ${all.filter(t => t.peeked).length} voided for peeking.`)
if (completedBase.length && graderErrors.length / completedBase.length > MAX_GRADER_ERROR_RATE) {
  log(`HALT: grader errors on ${graderErrors.length} of ${completedBase.length} completed trials. Treat the grader as broken.`)
  return {
    round: ROUND,
    halted: 'broken grader',
    examples: graderErrors.slice(0, 10).map(t => ({ id: t.id, error: t.grader_error, result_path: t.result_path })),
    skips,
    ledger: ledgerOut(),
  }
}

phase('Judge')
log(JUDGE_NOTE)
await parallel(TICKETS_IN_RUN.map(ticket => () => judgeTicket(ticket, 'base', 'Judge')))

phase('Top-up')
const split = cells.filter(cell => {
  const v = all.filter(t => t.kind === 'base' && t.config === cell.config && t.ticket === cell.ticket && valid(t))
  const p = v.filter(t => t.pass).length
  return v.length > 0 && p > 0 && p < v.length
})
let topupLeft = TOPUP_MAX
const topupCells = []
for (const cell of split) {
  const n = Math.min(TOPUP_PER_CELL, topupLeft)
  if (n <= 0) {
    skips.push({ what: `top-up ${cell.key}`, reason: `top-up trial cap of ${TOPUP_MAX}` })
    continue
  }
  topupLeft -= n
  topupCells.push({ ...cell, n })
}
log(`${split.length} split cells. ${topupCells.length} topped up with up to ${TOPUP_PER_CELL} trials each.`)

await pipeline(
  topupCells,
  async cell => {
    const ts = await parallel(
      Array.from({ length: cell.n }, (_, i) => () => runTrial(cell.config, cell.ticket, TRIALS + i + 1, 'topup')),
    )
    all.push(...ts)
    return { cell, ts }
  },
  async ({ cell, ts }) => {
    await gradeCell(cell, ts, 'Top-up')
    return cell
  },
)
const topupTickets = [...new Set(topupCells.map(c => c.ticket))]
await parallel(topupTickets.map(ticket => () => judgeTicket(ticket, 'topup', 'Top-up')))

phase('Synthesis')
const mean = xs => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : null)
const rate = (xs, f) => (xs.length ? xs.filter(f).length / xs.length : null)
const num = (t, k) => (typeof t[k] === 'number' ? t[k] : 0)

function summarize(ts) {
  const done = ts.filter(valid)
  const toned = done.filter(t => typeof t.tone_score === 'number')
  return {
    planned: ts.length,
    completed: done.length,
    voided_peek: ts.filter(t => t.peeked).length,
    harness_error: ts.filter(t => t.status === 'harness_error' || t.status === 'rate_limited').length,
    grader_error: ts.filter(t => t.grader_error).length,
    skipped_cap: ts.filter(t => t.status === 'skipped_cap').length,
    category_acc: r3(rate(done, t => t.category_ok)),
    priority_acc: r3(rate(done, t => t.priority_ok)),
    pass_rate: r3(rate(done, t => t.pass)),
    tone_judged: toned.length,
    tone_mean: r3(mean(toned.map(t => t.tone_score))),
    tone_pass_rate: r3(rate(toned, t => t.tone_pass)),
    runtime_s_mean: r3(mean(done.map(t => num(t, 'runtime_s')))),
    tool_calls_mean: r3(mean(done.map(t => num(t, 'tool_calls')))),
    tool_errors_mean: r3(mean(done.map(t => num(t, 'tool_errors')))),
    tokens_mean: r3(mean(done.map(t => num(t, 'input_tokens') + num(t, 'output_tokens')))),
    cost_usd_total: r2(ts.reduce((a, t) => a + num(t, 'cost_usd'), 0)),
  }
}

const byConfig = kind =>
  Object.fromEntries(CONFIGS.map(c => [c, summarize(all.filter(t => t.config === c && (kind === 'all' || t.kind === kind)))]))

const cellTable = cells.map(cell => {
  const mine = all.filter(t => t.config === cell.config && t.ticket === cell.ticket && valid(t))
  const b = mine.filter(t => t.kind === 'base')
  const u = mine.filter(t => t.kind === 'topup')
  return {
    cell: cell.key,
    base: `${b.filter(t => t.pass).length}/${b.length}`,
    topup: u.length ? `${u.filter(t => t.pass).length}/${u.length}` : null,
  }
})

const voided = all.filter(t => t.peeked).map(t => ({ id: t.id, evidence: t.peek_evidence }))

// Primary metrics use base trials only, so top-ups do not overweight split cells.
// Compare primary against the saved prediction. with_topup is for cell stability.
const summary = {
  round: ROUND,
  dry_run: !!ONLY,
  out_dir: OUT,
  configs: CONFIGS,
  tickets: TICKETS_IN_RUN.length,
  trials_per_cell: TRIALS,
  primary: byConfig('base'),
  with_topup: byConfig('all'),
  split_cells: split.map(c => c.key),
  cells: cellTable,
  voided,
  skips,
  ledger: ledgerOut(),
  judge_note: JUDGE_NOTE,
}

const failing = all.filter(t => valid(t) && (!t.pass || t.tone_pass === false))
const sample = CONFIGS.flatMap(c => failing.filter(t => t.config === c).slice(0, 40))
const fa = failing.length
  ? await paidAgent(null, 0, 'failure analysis', failurePrompt(sample, failing.length), {
      label: 'failure analysis',
      phase: 'Synthesis',
      schema: FAIL_SCHEMA,
    })
  : { out: { types: [], grader_bugs_suspected: [], notes: 'No graded trial failed. The next round needs harder tasks or stricter graders.' } }

const faOut = fa.out || { error: fa.error || 'failure analysis skipped' }
const critic = await paidAgent(null, 0, 'completeness critic', criticPrompt(summary, faOut), {
  label: 'completeness critic',
  phase: 'Synthesis',
  schema: CRITIC_SCHEMA,
})

log(`Done. Spent $${r2(pools.trial.spent)} on trials and about $${r2(pools.judge.spent)} on judging. ${skips.length} skips. ${voided.length} voided.`)

return {
  ...summary,
  failure_analysis: faOut,
  critic: critic.out || { error: critic.error || 'critic skipped' },
  trials: all.map(t => ({
    id: t.id,
    kind: t.kind,
    status: t.status,
    pass: t.pass ?? null,
    category_ok: t.category_ok ?? null,
    priority_ok: t.priority_ok ?? null,
    tone_score: t.tone_score ?? null,
    tone_pass: t.tone_pass ?? null,
    peeked: !!t.peeked,
    grader_error: t.grader_error ?? null,
    judge_error: t.judge_error ?? null,
